// Integrated Native research replay. Geometry uses screen_tracker.h unchanged.
// Calibration and measurement sample the same screen coordinates from padded input.
#include "screen_tracker.h"
#include <sstream>
#include <string>
using screen::Image;
using screen::Matrix;
using screen::Point;
constexpr double pi=3.14159265358979323846;
using Clock=std::chrono::steady_clock;
struct Frame {double t;uint32_t source;Image pixels;Matrix h=screen::identity;bool valid=true;double iou=0;};
struct Node {double x,y,mid,scale,orientation,score,min_radius,zero=0;Image calibration;};
struct Feature {double a=0;std::array<double,4> phase{},radius{};bool valid=true;};
struct Track {double previous=0,unwrapped=0;int integer=0,origin=0,last=-1,outlier=0;};
struct Decision {int count=0,valid=0,repairs=0,ambiguous=0,direction=0;std::array<int,4> pair{};};
struct Row {int index,count,delta,confirmation,valid,repairs,ambiguous;bool complete,pending;std::array<int,4> pairs;};
double wrap(double x){return std::remainder(x,2*pi);}
double sample(const Frame& f,int n,double x,double y,double ox,double oy){auto p=screen::project(f.h,x+ox,y+oy);if(p[0]<0||p[1]<0||p[0]>n-1||p[1]>n-1)throw std::runtime_error("sample outside padded image");return screen::at(f.pixels,n,p[0],p[1]);}
double patch(const Frame& f,int n,double x,double y,double ox,double oy){double a=0;for(int j=-1;j<=1;++j)for(int i=-1;i<=1;++i)a+=sample(f,n,x+i,y+j,ox,oy);return a/9;}
double mean(const Image& a){return std::accumulate(a.begin(),a.end(),0.)/a.size();}
double correlation(const Image& a,const Image& b){double am=mean(a),bm=mean(b),aa=0,bb=0,ab=0;for(size_t i=0;i<a.size();++i){double x=a[i]-am,y=b[i]-bm;aa+=x*x;bb+=y*y;ab+=x*y;}return ab/std::max(1e-12,std::sqrt(aa*bb));}
bool solve4(double m[4][5],std::array<double,4>& v){for(int k=0;k<4;++k){int pivot=k;for(int j=k+1;j<4;++j)if(std::abs(m[j][k])>std::abs(m[pivot][k]))pivot=j;if(std::abs(m[pivot][k])<1e-10)return false;for(int j=k;j<5;++j)std::swap(m[k][j],m[pivot][j]);double d=m[k][k];for(int j=k;j<5;++j)m[k][j]/=d;for(int i=0;i<4;++i)if(i!=k){double a=m[i][k];for(int j=k;j<5;++j)m[i][j]-=a*m[k][j];}}for(int j=0;j<4;++j)v[j]=m[j][4];return true;}
Image gradient_smooth(const Image& a){std::array<double,5> k{};double total=0;for(int i=-2;i<=2;++i){k[i+2]=std::exp(-i*i/(2*.7*.7));total+=k[i+2];}for(double& v:k)v/=total;Image tmp(4096),b(4096);for(int y=0;y<64;++y)for(int x=0;x<64;++x)for(int j=-2;j<=2;++j)tmp[y*64+x]+=k[j+2]*a[y*64+std::clamp(x+j,0,63)];for(int y=0;y<64;++y)for(int x=0;x<64;++x)for(int j=-2;j<=2;++j)b[y*64+x]+=k[j+2]*tmp[std::clamp(y+j,0,63)*64+x];return b;}
Point gradient_center(const std::vector<Frame>& frames,int n,double ox,double oy,double& residual){
 struct Equation {std::array<double,4> a;double b,weight;};std::vector<Equation> equations;
 for(const auto& f:frames){Image image(4096);for(int y=0;y<64;++y)for(int x=0;x<64;++x)image[y*64+x]=sample(f,n,x,y,ox,oy);image=gradient_smooth(image);
  for(int y=10;y<54;++y)for(int x=10;x<54;++x){double r=std::hypot(x-31.5,y-31.5);if(r<4||r>22)continue;double gx=(image[y*64+x+1]-image[y*64+x-1])/2,gy=(image[(y+1)*64+x]-image[(y-1)*64+x])/2;double magnitude=std::hypot(gx,gy);if(magnitude<.02)continue;double xx=(x-31.5)/31.5,yy=(y-31.5)/31.5;equations.push_back({{2*gy*xx+2*gx*yy,2*gy*yy-2*gx*xx,gy,-gx},2*gx*yy,1});}
 }
 if(equations.size()<200)throw std::runtime_error("insufficient calibration gradients");std::array<double,4> v{};
 for(int iteration=0;iteration<6;++iteration){double m[4][5]{};for(auto e:equations)for(int i=0;i<4;++i){for(int j=0;j<4;++j)m[i][j]+=e.weight*e.a[i]*e.a[j];m[i][4]+=e.weight*e.a[i]*e.b;}if(!solve4(m,v))throw std::runtime_error("ill-conditioned gradient center");Image errors;for(auto e:equations){double err=-e.b;for(int j=0;j<4;++j)err+=e.a[j]*v[j];errors.push_back(std::abs(err));}residual=screen::quantile(errors,.5);double threshold=std::max(.003,2.2*residual);for(size_t j=0;j<equations.size();++j)equations[j].weight=std::min(1.,threshold/std::max(1e-12,errors[j]));}
 double a=v[0],b=v[1],c=1-a,det=a*c-b*b;if(a<=0||c<=0||det<.02)throw std::runtime_error("non-elliptic calibration gradients");double cx=31.5-15.75*(c*v[2]-b*v[3])/det,cy=31.5-15.75*(a*v[3]-b*v[2])/det;
 if(cx<16||cx>48||cy<16||cy>48)throw std::runtime_error("gradient center outside screen interior");return {cx,cy};
}
int main(int argc,char** argv){try{
 if(argc<6){std::cerr<<"padded96.frc calibration_start calibration_end end frames.csv [--timing]\n";return 2;}bool timing=false;for(int j=6;j<argc;++j){if(std::string(argv[j])=="--timing")timing=true;else throw std::runtime_error("unknown option");}
 double start=std::stod(argv[2]),cal_end=std::stod(argv[3]),end=std::stod(argv[4]);const double ox=16,oy=58.*96/345;
 std::ifstream input(argv[1],std::ios::binary);char magic[4];input.read(magic,4);int n=screen::read<uint32_t>(input);screen::read<uint32_t>(input);screen::read<uint32_t>(input);auto count=screen::read<uint32_t>(input);screen::read<double>(input);if(n!=96)throw std::runtime_error("integrated replay expects padded96 real input");
 std::vector<Frame> frames;std::vector<Frame> calibration;Image reference(n*n);double previous=-1;
 for(uint32_t i=0;i<count;++i){screen::read<uint32_t>(input);double t=screen::read<double>(input);Frame f{t,i,Image(n*n)};for(double& v:f.pixels)v=screen::read<float>(input);if(t<=previous)throw std::runtime_error("nonmonotonic source timestamps");previous=t;if(t>=start&&t<=end){if(t<=cal_end){for(int p=0;p<n*n;++p)reference[p]+=f.pixels[p];calibration.push_back(f);}frames.push_back(std::move(f));}}
 if(calibration.size()<24)throw std::runtime_error("calibration too short");for(double& v:reference)v/=calibration.size();screen::Tracker tracker(reference,n);
 for(auto& f:calibration){auto o=tracker.push(f.pixels);f.h=o.transform;f.valid=o.accepted;if(!f.valid)throw std::runtime_error("calibration screen tracking failed");}
 double center_residual=0;auto center=gradient_center(calibration,n,ox,oy,center_residual);double cx=center[0],cy=center[1];Image primary;for(const auto& f:calibration)primary.push_back(patch(f,n,cx,cy,ox,oy));double lo0=screen::quantile(primary,.1),hi0=screen::quantile(primary,.9),mid0=(lo0+hi0)/2,scale0=(hi0-lo0)/2;if(scale0<.02)throw std::runtime_error("flat center signal");
 std::vector<Node> candidates;
 for(int direction=0;direction<8;++direction)for(int radius=2;radius<=16;++radius){double x=cx+radius*std::cos(direction*pi/4),y=cy+radius*std::sin(direction*pi/4);Image signal,radii;for(const auto& f:calibration)signal.push_back(patch(f,n,x,y,ox,oy));double lo=screen::quantile(signal,.1),hi=screen::quantile(signal,.9),mid=(lo+hi)/2,scale=(hi-lo)/2;if(scale<.02)continue;double previous_phase=0,net=0,absolute=0;for(size_t j=0;j<signal.size();++j){double a=(primary[j]-mid0)/scale0,b=(signal[j]-mid)/scale,ph=std::atan2(b,a);radii.push_back(std::hypot(a,b));if(j){double d=wrap(ph-previous_phase);net+=d;absolute+=std::abs(d);}previous_phase=ph;}if(std::abs(net)<3*pi||std::abs(net)<.9*absolute||*std::min_element(radii.begin(),radii.end())<.15)continue;double score=(1-std::abs(correlation(primary,signal)))*std::min(scale0,scale);candidates.push_back({x,y,mid,scale,net>=0?1.:-1.,score,.5*screen::quantile(radii,.1),0,signal});}
 std::vector<Node> nodes;while(nodes.size()<4){double best=-1;int which=-1;for(size_t j=0;j<candidates.size();++j){double diversity=1;bool near=false;for(auto q:nodes){near|=std::hypot(candidates[j].x-q.x,candidates[j].y-q.y)<3;diversity=std::min(diversity,1-std::abs(correlation(candidates[j].calibration,q.calibration)));}double score=candidates[j].score*std::sqrt(std::max(0.,diversity));if(!near&&score>best){best=score;which=int(j);}}if(which<0)break;nodes.push_back(candidates[which]);candidates.erase(candidates.begin()+which);}if(nodes.size()<2)throw std::runtime_error("insufficient phase pairs");
 // Common physical anchor: minima of the SAME center signal, never each node's minimum.
 double threshold=screen::quantile(primary,.25);std::vector<size_t> anchors;
 for(size_t i=0;i<primary.size();){if(primary[i]>threshold){++i;continue;}size_t first=i;while(i<primary.size()&&primary[i]<=threshold)++i;size_t at=first;for(size_t j=first;j<i;++j)if(primary[j]<primary[at])at=j;if(first>0&&i<primary.size())anchors.push_back(at);}
 // Multiple low-intensity fragments inside one revolution are one dark anchor.
 Image anchor_progress(primary.size());double previous_angle=0;for(size_t j=0;j<primary.size();++j){auto q=nodes[0];double a=q.orientation*std::atan2((q.calibration[j]-q.mid)/q.scale,(primary[j]-mid0)/scale0);anchor_progress[j]=j?anchor_progress[j-1]+wrap(a-previous_angle):a;previous_angle=a;}
 std::vector<size_t> unique;for(size_t j:anchors){if(!unique.empty()&&anchor_progress[j]-anchor_progress[unique.back()]<pi){if(primary[j]<primary[unique.back()])unique.back()=j;}else unique.push_back(j);}anchors=unique;
 if(anchors.size()<2)throw std::runtime_error("fewer than two complete dark-center calibration anchors");
 double anchor_spread=0;for(auto& node:nodes){double sx=0,sy=0;Image angles;for(size_t j:anchors){double ph=node.orientation*std::atan2((node.calibration[j]-node.mid)/node.scale,(primary[j]-mid0)/scale0);angles.push_back(ph);sx+=std::cos(ph);sy+=std::sin(ph);}node.zero=std::atan2(sy,sx);for(double ph:angles)anchor_spread=std::max(anchor_spread,std::abs(wrap(ph-node.zero))/(2*pi));}if(anchor_spread>.2)throw std::runtime_error("inconsistent calibration dark phase");
 std::ofstream cal_log(std::string(argv[5])+".calibration.csv");cal_log<<std::setprecision(17)<<"source_frame,timestamp,primary";for(size_t k=0;k<nodes.size();++k)cal_log<<",phase"<<k;cal_log<<'\n';for(size_t j=0;j<calibration.size();++j){cal_log<<calibration[j].source<<','<<calibration[j].t<<','<<(primary[j]-mid0)/scale0;for(auto q:nodes)cal_log<<','<<q.orientation*std::atan2((q.calibration[j]-q.mid)/q.scale,(primary[j]-mid0)/scale0);cal_log<<'\n';}
 std::ofstream model(std::string(argv[5])+".model.json");model<<std::setprecision(17)<<"{\"center\":["<<cx<<','<<cy<<"],\"gradient_residual\":"<<center_residual<<",\"anchor_spread_cycles\":"<<anchor_spread<<",\"dark_anchor_frames\":[";for(size_t j=0;j<anchors.size();++j){if(j)model<<',';model<<calibration[anchors[j]].source;}model<<"],\"nodes\":[";for(size_t k=0;k<nodes.size();++k){if(k)model<<',';auto q=nodes[k];model<<"{\"x\":"<<q.x<<",\"y\":"<<q.y<<",\"zero\":"<<q.zero<<",\"orientation\":"<<q.orientation<<",\"min_radius\":"<<q.min_radius<<'}';}model<<"]}\n";
 std::vector<Feature> features;features.reserve(frames.size());std::vector<Row> rows;std::vector<std::array<double,3>> timings;std::vector<Track> tracks(nodes.size());int fused=0,confirmed=0;bool complete=true;size_t cal_count=calibration.size();
 auto advance=[&](std::vector<Track>& states,int i,int limit,int prior){Decision out;double pos=0,neg=0,fp=0,fn=0;for(size_t k=0;k<nodes.size();++k){auto st=states[k];if(features[i].radius[k]>=nodes[k].min_radius&&st.last>=0){double d=wrap(features[i].phase[k]-st.previous);if(std::abs(d)>.15&&std::abs(d)<.8*pi){if(d>0)++pos;else ++neg;}}for(int j=i;j<limit;++j)if(features[j].valid&&features[j+1].valid&&features[j].radius[k]>=nodes[k].min_radius&&features[j+1].radius[k]>=nodes[k].min_radius){double d=wrap(features[j+1].phase[k]-features[j].phase[k]);if(std::abs(d)>.15&&std::abs(d)<.8*pi){if(d>0)fp+=1./(j-i+1);else fn+=1./(j-i+1);}}}int direction=pos>=2&&pos>neg?1:(neg>=2&&neg>pos?-1:(fp>fn+1?1:(fn>fp+1?-1:0)));out.direction=direction;
  std::vector<int> values,used;for(size_t k=0;k<nodes.size();++k){auto& st=states[k];if(!features[i].valid||features[i].radius[k]<nodes[k].min_radius)continue;double ph=features[i].phase[k];if(st.last<0){st.unwrapped=ph;st.integer=st.origin=int(std::floor(ph/(2*pi)));}else{double d=wrap(ph-st.previous);if(std::abs(d)>.8*pi){++out.ambiguous;if(direction*d<0){d+=direction*2*pi;++out.repairs;}}st.unwrapped+=d;}st.previous=ph;st.last=i;double boundary=st.unwrapped/(2*pi);while(boundary>st.integer+1+.02)++st.integer;while(boundary<st.integer-.02)--st.integer;values.push_back(st.integer-st.origin);used.push_back(int(k));}
  int best_votes=0;out.count=prior;for(int value:values){int votes=int(std::count(values.begin(),values.end(),value));if(votes>best_votes||(votes==best_votes&&std::abs(value-prior)<std::abs(out.count-prior))){best_votes=votes;out.count=value;}}if(best_votes<2)out.count=prior;out.valid=int(values.size());
  if(best_votes>=3)for(size_t j=0;j<used.size();++j){auto& st=states[used[j]];if(values[j]!=out.count){if(++st.outlier>=4){int correction=out.count-values[j];st.integer+=correction;st.unwrapped+=correction*2*pi;st.outlier=0;++out.repairs;}}else st.outlier=0;}
  for(size_t k=0;k<nodes.size();++k)out.pair[k]=states[k].integer-states[k].origin;return out;
 };
 auto commit=[&](int index,int received,bool eof){auto d=advance(tracks,index,received,fused);fused=d.count;int delta=fused-confirmed;bool pending=eof&&delta!=0;if(!frames[index].valid||std::abs(delta)>1){complete=false;pending=true;}if(!pending)confirmed=fused;else complete=false;rows.push_back({index,confirmed,pending?0:delta,received,d.valid,d.repairs,d.ambiguous,complete,pending,d.pair});};
 std::ofstream online(std::string(argv[5])+".online.csv");online<<"source_frame,timestamp,count_available_now,complete\n";int next=int(cal_count);
 for(size_t i=0;i<frames.size();++i){auto tick=timing?Clock::now():Clock::time_point{};auto& f=frames[i];if(i<cal_count)f.h=calibration[i].h;else{auto o=tracker.push(f.pixels);f.h=o.transform;f.valid=o.accepted;f.iou=o.iou_after;}Feature feature;feature.valid=f.valid;if(f.valid){feature.a=(patch(f,n,cx,cy,ox,oy)-mid0)/scale0;for(size_t k=0;k<nodes.size();++k){const auto& q=nodes[k];double b=(patch(f,n,q.x,q.y,ox,oy)-q.mid)/q.scale;feature.radius[k]=std::hypot(feature.a,b);feature.phase[k]=wrap(q.orientation*std::atan2(b,feature.a)-q.zero);}}features.push_back(feature);
  if(i>=cal_count){if(int(i)>=next+4){commit(next,int(i),false);++next;}double us=timing?std::chrono::duration<double,std::micro>(Clock::now()-tick).count():0;if(timing)timings.push_back({double(f.source),f.t,us});online<<std::setprecision(17)<<f.source<<','<<f.t<<','<<confirmed<<','<<complete<<'\n';}
 }
 auto end_tick=timing?Clock::now():Clock::time_point{};while(next<int(frames.size())){commit(next,int(frames.size())-1,true);++next;}if(timing&&!timings.empty())timings.back()[2]+=std::chrono::duration<double,std::micro>(Clock::now()-end_tick).count();
 std::ofstream out(argv[5]),events(std::string(argv[5])+".events.csv");out<<std::setprecision(17)<<"timestamp,calibrating,source_frame,count,event_direction,confirmed_at,confirmation_frame,delay_frames,tail_pending,complete,valid_pairs,repairs,ambiguous,primary,tracking_valid,tracking_iou,pair0,phase0,pair1,phase1,pair2,phase2,pair3,phase3\n";events<<std::setprecision(17)<<"event_frame,event_timestamp,direction,confirmation_frame,confirmation_timestamp\n";
 for(auto r:rows){const auto& f=frames[r.index];const auto& c=frames[r.confirmation];out<<f.t<<",0,"<<f.source<<','<<r.count<<','<<r.delta<<','<<c.t<<','<<c.source<<','<<c.source-f.source<<','<<r.pending<<','<<r.complete<<','<<r.valid<<','<<r.repairs<<','<<r.ambiguous<<','<<features[r.index].a<<','<<f.valid<<','<<f.iou;for(size_t k=0;k<nodes.size();++k)out<<','<<r.pairs[k]<<','<<features[r.index].phase[k];out<<'\n';if(r.delta)events<<f.source<<','<<f.t<<','<<r.delta<<','<<c.source<<','<<c.t<<'\n';}
 if(timing){std::ofstream file(std::string(argv[5])+".core.csv");file<<"source_frame,timestamp,core_us\n";for(auto r:timings)file<<std::setprecision(17)<<r[0]<<','<<r[1]<<','<<r[2]<<'\n';}
 std::cout<<std::setprecision(9)<<"center="<<cx<<','<<cy<<" nodes="<<nodes.size()<<" anchors="<<anchors.size()<<" count="<<confirmed<<" complete="<<complete<<" frames="<<rows.size()<<'\n';return complete?0:3;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
